import{_ as r,l as i,o as e,c as n,v as t,p as s,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const Q=JSON.parse('{"title":"PQ 向量索引","description":"","frontmatter":{"title":"PQ 向量索引","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pq-vector-index.md","filePath":"llm/pq-vector-index.md","lastUpdated":1789023840000}'),h={name:"llm/pq-vector-index.md"};function E(P,a,m,u,_,A){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="pq-向量索引" tabindex="-1">PQ 向量索引 <a class="header-anchor" href="#pq-向量索引" aria-label="Permalink to &quot;PQ 向量索引&quot;">​</a></h1><div class="epigraph"><p>把向量切成子段，每段用小码本表示，内存按字节计而不是按浮点计。近似近邻的误差里，有一部分来自量化而不是来自图。</p><footer>—— Jégou, Douze, Schmid, Product Quantization</footer></div><p><a href="/llm/hnsw-ivf">上一课</a>用图或列表缩小扫描范围，向量仍常是 float32。十亿级库会先爆内存。Jégou 等人的乘积量化（Product Quantization, PQ）把向量分成 \\(M\\) 段，每段量化到码本下标，距离用查表近似。缺口是量化误差进检索。后课 RAG 对微调默认：索引可以很省，但过时知识不一定该靠更密的码本解决。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PQ 存 \\(M\\) 个 uint8（或更短）代替 \\(d\\) 个 float。非对称距离：查询保持浮点，文档用码字，避免查询也被量化毁几何。IVF+PQ 是常见组合：先 IVF 缩小列表，列表内用 PQ 距离。误差：码本对数据分布失配、段切分切坏相关维、\\(M\\) 太小。难负例附近的近邻差会被量化抹平，细粒度检索先坏。</p><p>与 Matryoshka 不同：MRL 是训练时排维；PQ 是推理时有损编码。二者可叠：先截维再 PQ。</p><p><span class="marginnote">重建向量再算精确距离只对短候选列表可行。重排应用未量化向量或更高精度残差（OPQ / 残差量化）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练码本：在文档向量上 k-means（或 OPQ 先旋转）。索引卡写：\\(M\\)、每段比特、是否 OPQ、是否 IVF。评测：同一查询集上 float 精确 vs PQ 的 Recall 差，按延迟分层。RAG 最终 \\(k\\) 很小时应对 PQ 候选用精确向量重排，把量化留在召回段。</p>',9)),(e(),s(c,null,{default:o(()=>[p(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22float%20%E5%90%91%E9%87%8F%22%5D%20--%3E%20SPLIT%5B%22%E5%88%87%E6%88%90%20M%20%E6%AE%B5%22%5D%0A%20%20SPLIT%20--%3E%20CB%5B%22%E6%AE%B5%E5%86%85%E7%A0%81%E6%9C%AC%22%5D%0A%20%20CB%20--%3E%20CODE%5B%22%E7%9F%AD%E7%A0%81%22%5D%0A%20%20Q%5B%22%E6%B5%AE%E7%82%B9%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20LUT%5B%22%E9%9D%9E%E5%AF%B9%E7%A7%B0%E6%9F%A5%E8%A1%A8%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20CODE%20--%3E%20LUT%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>段内 k-means 把局部空间换成最近码心。乘积结构假设段近似独立；相关维被切开则码本浪费。OPQ 学旋转，让段更独立。距离查表是码心与查询子段的预计算点积/欧氏，加速来自不碰原向量。误差在决策边界上被放大——正是难查询切片。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>PQ 不加密、不防投毒，只压缩。下一课把「知识放索引还是放权重」写成 RAG 对微调。再下一课投毒：压缩后的索引同样会被污染文档击中。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PQ 用子空间码本换内存，误差要单独报 Recall 差。</li><li>查询侧保持浮点；最终短列表用精确重排。</li><li>与 IVF、MRL 可叠加，职责不同。</li><li>出处：Jégou, Douze, Schmid 乘积量化。</li></ul>',6))])}const B=r(h,[["render",E]]);export{Q as __pageData,B as default};
